void jwplcHMISetup()
{
    JWPLC_Display.setFields(
        HMI_FIELDS,
        sizeof(HMI_FIELDS) / sizeof(HMI_FIELDS[0]));
    JWPLC_Display.setUserPageCount(2);
    JWPLC_Display.setUserPage(PAGE_PROCESO);
    // Indicador NN/TT (barra de navegación)
#ifdef JWPLC_UI_HAS_PAGE_INDICATOR_CONFIG
    JWPLC_Display.setPageIndicator(false);
#endif
    JWPLC_Display.setUserRefreshMode(USER_REFRESH_PERIODIC);

    // Pantalla IDLE (Designer · Pantalla y arranque)
    JWPLC_Display.setIdleWakeMode(JWPLC_DisplayClass::IDLE_WAKE_ANY_BUTTON);
    JWPLC_Display.setIdleReturnMode(JWPLC_DisplayClass::IDLE_RETURN_ESC_ONLY);
    JWPLC_Display.enterUserUI();
}

// Barra de Navegación HMI Autogenerada (ST7789)
// Pestaña de la página actual: posicionada en el selector (◀ ▶, fondo de
// color) o seleccionada dentro de la página (OK, fondo blanco y doble marco).
static void jwplcDrawPageNavTab(uint8_t activePage, bool selecting)
{
    JWPLC_TFTClass &tft = JWPLC_Display.tft();
    tft.setTextSize(1);

    switch (activePage)
    {
    case 0:
        if (selecting)
        {
            tft.fillRoundRect(68, 148, 90, 20, 3, 0x073F);
            tft.setCursor(92, 154);
            tft.setTextColor(0x0000);
            tft.print("PROCESO");
        }
        else
        {
            tft.fillRoundRect(68, 148, 90, 20, 3, 0xFFFF);
            tft.drawRoundRect(68, 148, 90, 20, 3, 0x032E);
            tft.drawRoundRect(70, 150, 86, 16, 1, 0x032E);
            tft.setCursor(92, 154);
            tft.setTextColor(0x032E);
            tft.print("PROCESO");
        }
        break;
    case 1:
        if (selecting)
        {
            tft.fillRoundRect(161, 148, 90, 20, 3, 0xFC80);
            tft.setCursor(185, 154);
            tft.setTextColor(0x0000);
            tft.print("EQUIPOS");
        }
        else
        {
            tft.fillRoundRect(161, 148, 90, 20, 3, 0xFFFF);
            tft.drawRoundRect(161, 148, 90, 20, 3, 0x7200);
            tft.drawRoundRect(163, 150, 86, 16, 1, 0x7200);
            tft.setCursor(185, 154);
            tft.setTextColor(0x7200);
            tft.print("EQUIPOS");
        }
        break;
    default:
        break;
    }
}

// Se dibuja una vez por página desde jwplcUIPageEnter().
static void jwplcDrawPageNavBar(uint8_t activePage)
{
    JWPLC_TFTClass &tft = JWPLC_Display.tft();
    tft.setTextSize(1);

    switch (activePage)
    {
    case 0:
        tft.fillRoundRect(0, 147, 320, 22, 3, 0x0000);
        tft.fillRoundRect(161, 148, 90, 20, 3, 0x0000);
        tft.drawRoundRect(161, 148, 90, 20, 3, 0xFC80);
        tft.setCursor(185, 154);
        tft.setTextColor(0xFC80);
        tft.print("EQUIPOS");
        break;
    case 1:
        tft.fillRoundRect(0, 147, 320, 22, 3, 0x0000);
        tft.fillRoundRect(68, 148, 90, 20, 3, 0x0000);
        tft.drawRoundRect(68, 148, 90, 20, 3, 0x073F);
        tft.setCursor(92, 154);
        tft.setTextColor(0x073F);
        tft.print("PROCESO");
        break;
    default:
        break;
    }

    jwplcDrawPageNavTab(activePage, JWPLC_Display.isUserPageSelection());
}

// Selector <-> contenido sin cambiar de página: el firmware redibuja sólo la
// pestaña activa, con el bus tomado (Alpha15).
extern "C" void jwplcUIPageModeChanged(uint8_t page, bool selecting)
{
    jwplcDrawPageNavTab(page, selecting);
}

// Gráfica estática por página (se dibuja una vez al entrar a la página).
// Para lógica propia al cambiar de página, define en el sketch:
//   extern "C" void jwplcHMIUserPageEnter(uint8_t page) { ... }
extern "C" void jwplcHMIUserPageEnter(uint8_t page) __attribute__((weak));

void jwplcUIPageEnter(uint8_t page)
{
    JWPLC_TFTClass &tft = JWPLC_Display.tft();

    switch (page)
    {
    case PAGE_PROCESO:
        // FIELD_RECT_2
        tft.fillRect(0, 0, 319, 16, 0x000F);
        tft.drawRect(0, 0, 319, 16, 0x000F);
        // Planta de agua
        tft.setCursor(4, 5);
        tft.setTextSize(1);
        tft.setTextColor(0xFFFF);
        tft.print("Planta de agua");
        break;

    default:
        break;
    }

    jwplcDrawPageNavBar(page);

    if (jwplcHMIUserPageEnter)
    {
        jwplcHMIUserPageEnter(page);
    }
}

// Sincronización gráfica autogenerada (cada tick de refresco).
// Sólo setters: el runtime redibuja únicamente los campos que cambiaron.
// La lógica de aplicación debe permanecer en loop().
void jwplcUIUpdate()
{
    switch (JWPLC_Display.userPage())
    {
    case PAGE_PROCESO:
        // Página 01 · Proceso
        JWPLC_Display.setIconState(ICON_TANQUE, tanque);
        JWPLC_Display.setIconState(ICON_ENTRADA, valvulaEntrada);
        JWPLC_Display.setIconState(ICON_BOMBA, bomba);
        JWPLC_Display.setIconState(ICON_AGITADOR, agitador);
        JWPLC_Display.setIconState(ICON_PARO, paro);
        JWPLC_Display.setBar(FIELD_NIVEL, nivel);
        JWPLC_Display.setIconState(ICON_AUTO, modoAuto);
        JWPLC_Display.setIconState(ICON_ALARMA, alarma);
        JWPLC_Display.setValue(FIELD_CAUDAL, caudal);
        break;

    case PAGE_EQUIPOS:
        // Página 02 · Equipos
        JWPLC_Display.setIconState(ICON_CINTA, cinta);
        JWPLC_Display.setIconState(ICON_SILO, silo);
        JWPLC_Display.setIconState(ICON_VENTILADOR, ventilador);
        JWPLC_Display.setIconState(ICON_COMPRESOR, compresor);
        JWPLC_Display.setIconState(ICON_RESISTENCIA, resistencia);
        JWPLC_Display.setIconState(ICON_TEMP, temperatura);
        JWPLC_Display.setIconState(ICON_PRESION, presion);
        JWPLC_Display.setIconState(ICON_BALIZA, baliza);
        break;

    default:
        break;
    }
}
